<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { Download, RefreshCw, Sparkles } from '@lucide/vue'
import { can } from '../../permissions.js'
import { notifyError } from '../../api.js'
import { UiMessage } from '../../ui/feedback.js'
import { createClientId } from '../../clientId.js'
import { monitoringAll, monitoringExport, monitoringRead, monitoringWrite } from '../../monitoring/api.js'
import { dependencyKinds, durationLabel, findingKinds, hypothesisPayload, intervalStates, metricRatio, metricRows, monitoringEvidenceRows, monitoringTime, overallMetrics, reasonText, recordBody, reviewStates, runIsActive, stateLabel, stateTone, trackLabels, unwrapOutputs } from '../../monitoring/helpers.js'
import MonitoringTimeline from './MonitoringTimeline.vue'
const props = defineProps({ run: Object, devices: { type: Array, default: () => [] }, profiles: { type: Array, default: () => [] }, deviceId: { type: String, default: '' } })
const emit = defineEmits(['navigate','refresh'])
const root = ref(null), loading = ref(false), error = ref(''), snapshot = ref(null), metrics = ref([]), intervals = ref([]), groups = ref([]), findings = ref([]), evidence = ref([]), reviews = ref([]), hypotheses = ref([]), metricId = ref(''), downloading = ref(false)
const deviceFilter = ref(''), productFilter = ref(''), departmentFilter = ref(''), regionFilter = ref(''), kindFilter = ref(''), reviewFilter = ref(''), findingPage = ref(1)
const factDialog = ref(false), factType = ref(''), fact = ref(null), history = ref([]), detailError = ref(''), reviewSaving = ref(false), review = reactive({ result: '', explanation: '', correctsId: '', idempotencyKey: '' })
const groupDialog = ref(false), group = ref(null), hypothesisAt = ref(null), hypothesisSaving = ref(false), hypothesisError = ref(''), hypothesisKey = ref('')
const aiJobs = ref([]), aiId = ref(''), aiError = ref(''), aiBusy = ref(false), useKnowledge = ref(false)
let generation = 0, detailGeneration = 0, groupGeneration = 0, aiTimer = 0, disposed = false
const deviceName = id => props.devices.find(row=>row.id===id)?.name || id || '未指定设备'
const deviceMetadata = id => props.devices.find(row=>row.id===id) || {}
const profileName = id => { const value=props.profiles.map(recordBody).find(row=>row.revisionId===id);return value?`策略版本 ${value.revisionVersion} · ${value.merge} · ${value.importance || '未设重要性标签'}`:'固定历史策略' }
const matchesDevice = id => (!props.deviceId || id===props.deviceId) && (!deviceFilter.value || id===deviceFilter.value) && (!productFilter.value || deviceMetadata(id).productId===productFilter.value) && (!departmentFilter.value || deviceMetadata(id).tags?.department===departmentFilter.value) && (!regionFilter.value || deviceMetadata(id).tags?.region===regionFilter.value)
const visibleMetrics = computed(()=>metrics.value.filter(row=>matchesDevice(row.deviceId)))
const visibleIntervals = computed(()=>intervals.value.filter(row=>matchesDevice(row.deviceId)))
const selectedMetric = computed(()=>visibleMetrics.value.find(row=>row.id===metricId.value)||overallMetrics(visibleMetrics.value).find(row=>row.track==='data')||visibleMetrics.value[0])
const rank = computed(()=>overallMetrics(visibleMetrics.value).filter(row=>row.track==='data').sort((a,b)=>b.longestGapMs-a.longestGapMs || b.unavailableMs-a.unavailableMs || String(a.deviceId).localeCompare(String(b.deviceId))))
const selectedEvidence = computed(()=>{
 if(factType.value==='evidence')return fact.value?[fact.value]:[]
 const ids=fact.value?.evidenceIds||[];return evidence.value.filter(row=>ids.includes(row.id)||ids.includes(row.sourceId)||ids.includes(row.sampleId)||ids.includes(row.summary?.id))
})
const selectedIntervals = computed(()=>{const ids=fact.value?.evidenceIds||[];return intervals.value.filter(row=>ids.includes(row.id)||ids.includes(row.outputId))})
const latestReview = id => reviews.value.filter(row=>row.resourceId===id).sort((a,b)=>b.reviewedAt-a.reviewedAt||String(b.id).localeCompare(String(a.id)))[0]
const findingDevices = row => row.deviceId?[row.deviceId]:row.values?.deviceIds || groups.value.find(group=>group.id===row.values?.groupId)?.memberIds || []
const visibleFindings = computed(()=>findings.value.filter(row=>(!findingDevices(row).length||findingDevices(row).some(matchesDevice))&&(!kindFilter.value||row.kind===kindFilter.value)&&(!reviewFilter.value||(latestReview(row.id)?.result||'UNREVIEWED')===reviewFilter.value)))
const pageFindings = computed(()=>visibleFindings.value.slice((findingPage.value-1)*20,findingPage.value*20))
const visibleGroups = computed(()=>groups.value.filter(row=>row.memberIds?.some(matchesDevice)))
const groupHistory = computed(()=>hypotheses.value.filter(row=>row.groupId===group.value?.id).sort((a,b)=>b.createdAt-a.createdAt))
const options = field => [...new Set(props.devices.map(row=>field==='department'||field==='region'?row.tags?.[field]:row[field]).filter(Boolean))]
const productName = id => props.devices.find(row=>row.productId===id)?.productName || id
const activeAI = computed(()=>aiJobs.value.find(row=>row.id===aiId.value)||aiJobs.value[0])
const interpretation = computed(()=>activeAI.value?.interpretation||{})
const aiCoverage = computed(()=>activeAI.value?.coverage||interpretation.value.coverage)
const aiSections = [['observedWeaknesses','观察到的监测薄弱项'],['prioritizedChecks','建议核查顺序'],['dependencyObservations','接入依赖观察'],['limitations','解读限制']]
const detailTitle = computed(()=>factType.value==='finding'?(findingKinds[fact.value?.kind]||'监测发现'):factType.value==='interval'?'固定监测区间':'固定来源证据')
function stopAI(){clearTimeout(aiTimer);aiTimer=0}
async function loadAI(){const id=props.run?.id,token=generation;if(!id)return;try{const value=await monitoringRead('runs',id,'ai-jobs');if(token!==generation||disposed)return;aiJobs.value=(value.items||[]).slice().sort((a,b)=>b.createdAt-a.createdAt||String(b.id).localeCompare(String(a.id)));if(!aiJobs.value.some(row=>row.id===aiId.value))aiId.value=aiJobs.value[0]?.id||'';stopAI();if(aiJobs.value.some(row=>['QUEUED','RUNNING'].includes(row.status)))aiTimer=setTimeout(loadAI,2200)}catch(cause){if(token===generation&&!disposed){aiError.value=cause.message;stopAI()}}}
async function runAI(){if(aiBusy.value||!props.run?.snapshotId)return;const id=props.run.id,token=generation;aiBusy.value=true;aiError.value='';try{const current=await monitoringRead('runs',id);if(token!==generation||disposed)return;const row=await monitoringWrite('runs',id,'ai-jobs',{expectedVersion:current.version,idempotencyKey:createClientId(),useKnowledge:useKnowledge.value,reinterpret:!!activeAI.value});if(token!==generation||disposed)return;aiId.value=row.id;await loadAI()}catch(cause){if(token===generation&&!disposed)aiError.value=cause.message}finally{if(token===generation)aiBusy.value=false}}
async function load(){const id=props.run?.id,token=++generation;stopAI();detailGeneration++;groupGeneration++;factDialog.value=false;groupDialog.value=false;fact.value=null;group.value=null;history.value=[];metrics.value=[];intervals.value=[];groups.value=[];findings.value=[];evidence.value=[];reviews.value=[];hypotheses.value=[];snapshot.value=null;metricId.value='';error.value='';aiJobs.value=[];aiId.value='';aiError.value='';loading.value=false;aiBusy.value=false;reviewSaving.value=false;hypothesisSaving.value=false;if(!id||!props.run.snapshotId)return;loading.value=true;try{const values=await Promise.all([monitoringRead('runs',id,'snapshot'),monitoringAll('runs',id,'metrics'),monitoringAll('runs',id,'intervals'),monitoringAll('runs',id,'dependency-groups'),monitoringAll('runs',id,'findings'),monitoringAll('runs',id,'evidence'),monitoringAll('runs',id,'reviews'),monitoringAll('runs',id,'hypotheses')]);if(token!==generation||disposed)return;snapshot.value=values[0];metrics.value=metricRows(values[1].items);intervals.value=unwrapOutputs(values[2].items);groups.value=unwrapOutputs(values[3].items);findings.value=unwrapOutputs(values[4].items);evidence.value=monitoringEvidenceRows(values[5].items);reviews.value=values[6].items||[];hypotheses.value=values[7].items||[];metricId.value=overallMetrics(visibleMetrics.value).find(row=>row.track==='data')?.id||visibleMetrics.value[0]?.id||'';findingPage.value=1;await loadAI()}catch(cause){if(token===generation&&!disposed){error.value=cause.message;if(cause.status===403){snapshot.value=null;metrics.value=[];intervals.value=[];groups.value=[];findings.value=[];evidence.value=[]}}}finally{if(token===generation)loading.value=false}}
async function openFact(row,type='finding'){const token=++detailGeneration;groupDialog.value=false;fact.value=row;factType.value=type;factDialog.value=true;history.value=[];detailError.value='';reviewSaving.value=false;Object.assign(review,{result:'',explanation:'',correctsId:'',idempotencyKey:createClientId()});if(type!=='finding')return;try{const value=await monitoringAll('findings',row.id,'reviews',{runId:props.run.id});if(token===detailGeneration&&!disposed)history.value=value.items||[]}catch(cause){if(token===detailGeneration&&!disposed)detailError.value=cause.message}}
async function saveReview(){if(reviewSaving.value||factType.value!=='finding'||!fact.value)return;const id=fact.value.id,runId=props.run.id,token=detailGeneration;reviewSaving.value=true;detailError.value='';try{if(!review.result||!review.explanation.trim())throw new Error('请选择核实结果并填写实际核实依据');const current=await monitoringRead('runs',runId);if(token!==detailGeneration||disposed)return;const row=await monitoringWrite('findings',id,'reviews',{runId,expectedRunVersion:current.version,result:review.result,explanation:review.explanation.trim(),correctsId:review.correctsId,idempotencyKey:review.idempotencyKey});if(token!==detailGeneration||disposed)return;reviews.value=[...reviews.value.filter(value=>value.id!==row.id),row];history.value=[...history.value,row];Object.assign(review,{result:'',explanation:'',correctsId:'',idempotencyKey:createClientId()});UiMessage.success('监测发现核实记录已保存')}catch(cause){if(token===detailGeneration&&!disposed)detailError.value=cause.status===409?'任务或核实版本已变化，请重新读取后核实。':cause.message}finally{if(token===detailGeneration)reviewSaving.value=false}}
function openGroup(row){groupGeneration++;factDialog.value=false;group.value=row;hypothesisAt.value=row.start;hypothesisKey.value=createClientId();hypothesisError.value='';hypothesisSaving.value=false;groupDialog.value=true}
async function createHypothesis(){if(hypothesisSaving.value||!group.value)return;const currentGroup=group.value,runId=props.run.id,token=groupGeneration;hypothesisSaving.value=true;hypothesisError.value='';try{const current=await monitoringRead('runs',runId);if(token!==groupGeneration||disposed)return;const payload=hypothesisPayload(currentGroup,hypothesisAt.value,current.version,hypothesisKey.value);const row=await monitoringWrite('runs',runId,'hypotheses',payload);if(token!==groupGeneration||disposed)return;hypotheses.value=[...hypotheses.value.filter(value=>value.id!==row.id),row];hypothesisKey.value=createClientId();UiMessage.success('固定接入组假设影响已计算保存')}catch(cause){if(token===groupGeneration&&!disposed)hypothesisError.value=cause.status===409?'任务版本已变化，请重新读取接入组后计算。':cause.message}finally{if(token===groupGeneration)hypothesisSaving.value=false}}
async function exportReport(){if(downloading.value)return;downloading.value=true;try{await monitoringExport(props.run.id)}catch(cause){notifyError(cause)}finally{downloading.value=false}}
function raw(row){if(row.rawMessageId)emit('navigate','raw',{deviceId:row.deviceId,messageId:row.rawMessageId})}
function factLabel(id){if(findings.value.some(row=>row.id===id))return'监测发现';if(groups.value.some(row=>row.id===id))return'接入组依据';if(intervals.value.some(row=>row.id===id))return'监测区间';if(metrics.value.some(row=>row.id===id||row.outputId===id))return'区间指标';if(evidence.value.some(row=>row.id===id))return'来源证据';return'固定汇总'}
function selectFact(id){const f=findings.value.find(row=>row.id===id);if(f)return openFact(f);const g=groups.value.find(row=>row.id===id);if(g)return openGroup(g);const i=intervals.value.find(row=>row.id===id);if(i)return openFact(i,'interval');const ev=evidence.value.find(row=>row.id===id);if(ev)return openFact(ev,'evidence');const matched=metrics.value.filter(row=>row.id===id||row.outputId===id);if(matched.length){metricId.value=overallMetrics(matched).find(row=>row.track==='data')?.id||matched[0].id;root.value?.querySelector('.monitor-stat-grid')?.scrollIntoView({block:'start'});return}root.value?.querySelector('.monitor-snapshot')?.scrollIntoView({block:'start'})}
watch(()=>[props.run?.id,props.run?.snapshotId],load,{immediate:true});watch([deviceFilter,productFilter,departmentFilter,regionFilter,kindFilter,reviewFilter],()=>{findingPage.value=1})
onBeforeUnmount(()=>{disposed=true;generation++;detailGeneration++;groupGeneration++;stopAI()})
</script>
<template>
 <section ref="root" class="monitor-stack monitoring-results"><div class="monitor-toolbar"><h3 class="monitor-subtitle">固定连续性结果</h3><div class="monitor-actions"><ui-button size="small" :loading="loading" @click="load"><RefreshCw/>刷新结果</ui-button><ui-button v-if="run?.snapshotId&&can('GET /api/v1/monitoring-gaps/runs/:id/export')" size="small" :loading="downloading" @click="exportReport"><Download/>导出连续性报告</ui-button></div></div><ui-alert v-if="error" :title="error" type="error" :closable="false"><ui-button size="small" @click="load">重新读取</ui-button></ui-alert><ui-skeleton v-if="loading&&!metrics.length" :rows="5" animated/><ui-empty v-else-if="!run?.snapshotId" :description="runIsActive(run)?'任务正在形成固定区间，请稍后查看。':'该任务没有可用事实快照，请检查执行状态。'"/>
  <template v-else-if="snapshot"><div class="monitor-card monitor-stack monitor-snapshot"><div class="monitor-toolbar"><strong>快照版本 {{snapshot.version}} · 数据截至 {{monitoringTime(snapshot.dataCutoff)}}</strong><ui-tag :type="run.status==='PARTIAL'?'warning':'info'">{{stateLabel(run.status)}}</ui-tag></div><p class="monitor-meta">本次已授权设备 {{snapshot.deviceIds?.length || 0}} 个 · 固定输入 {{snapshot.inputHashes?.length || 0}} 块</p><ui-alert v-for="reason in snapshot.limitations || []" :key="reason" :title="reasonText(reason)" type="warning" :closable="false"/><p v-if="snapshot.missingSources?.length" class="monitor-hint">来源缺口：{{snapshot.missingSources.map(reasonText).join('、')}}</p><p v-if="snapshot.uncomputableMetrics?.length" class="monitor-hint">不可计算：{{snapshot.uncomputableMetrics.map(reasonText).join('、')}}</p><div class="monitor-table-scroll"><table class="monitor-native-table"><thead><tr><th>来源 / 版本</th><th>固定覆盖</th><th>读取时点</th><th>完整性及说明</th></tr></thead><tbody><tr v-for="source in snapshot.sources || []" :key="source.source+source.start"><td>{{source.source}}<p class="monitor-meta">{{source.version}}</p></td><td>{{monitoringTime(source.start)}} ～ {{monitoringTime(source.end)}}</td><td>{{monitoringTime(source.readAt)}}</td><td>{{source.complete?'已覆盖':'部分 / 未覆盖'}} {{reasonText(source.reason)}}</td></tr></tbody></table></div><ui-collapse v-if="snapshot.statistics?.qualitySnapshots?.length"><ui-collapse-item title="本任务固定引用的数据质量版本" name="quality"><article v-for="q in snapshot.statistics.qualitySnapshots" :key="q.id" class="monitor-card"><strong>数据质量快照版本 {{q.version}}</strong><p class="monitor-meta">关联任务 {{q.runId}} · 固定事实 {{q.factsHash}}</p><ui-button v-if="can('menu:dataQuality')&&can('menu:devices')" :data-monitor-quality-run="q.runId" text size="small" @click="emit('navigate','dataQuality',{runId:q.runId})">查看固定质量任务</ui-button><p v-for="reason in q.limitations || []" :key="reason" class="monitor-hint">{{reasonText(reason)}}</p></article></ui-collapse-item></ui-collapse></div>
   <div class="monitor-filter-row"><ui-select v-if="!deviceId" v-model="deviceFilter" clearable filterable placeholder="全部获授权设备"><ui-option v-for="row in devices" :key="row.id" :value="row.id" :label="row.name || row.id"/></ui-select><ui-select v-if="!deviceId" v-model="productFilter" clearable placeholder="全部产品"><ui-option v-for="id in options('productId')" :key="id" :value="id" :label="productName(id)"/></ui-select><ui-select v-if="options('department').length" v-model="departmentFilter" clearable placeholder="登记部门"><ui-option v-for="name in options('department')" :key="name" :value="name" :label="name"/></ui-select><ui-select v-if="options('region').length" v-model="regionFilter" clearable placeholder="登记区域"><ui-option v-for="name in options('region')" :key="name" :value="name" :label="name"/></ui-select></div><p v-if="options('department').length||options('region').length" class="monitor-hint">部门与区域只采用已登记设备标签。</p>
   <div v-if="selectedMetric" class="monitor-stack"><ui-select v-model="metricId" filterable placeholder="选择设备、轨道与策略"><ui-option v-for="m in visibleMetrics" :key="m.id" :value="m.id" :label="`${deviceName(m.deviceId)} · ${m.attributeId || '合并关键属性'} · ${trackLabels[m.track] || m.track} · ${m.profileId?profileName(m.profileId):'整体观察窗口'}`"/></ui-select><div class="monitor-stat-grid"><article><span class="monitor-meta">已知可用时长</span><strong>{{durationLabel(selectedMetric.availableMs)}}</strong><small>{{selectedMetric.availableMs}} ms</small></article><article><span class="monitor-meta">已知不可用时长</span><strong>{{durationLabel(selectedMetric.unavailableMs)}}</strong><small>{{selectedMetric.unavailableMs}} ms</small></article><article><span class="monitor-meta">未知时长</span><strong>{{durationLabel(selectedMetric.unknownMs)}}</strong><small>{{selectedMetric.unknownMs}} ms</small></article><article><span class="monitor-meta">计划观察时长</span><strong>{{durationLabel(selectedMetric.plannedMs)}}</strong><small>全窗口 {{selectedMetric.windowMs}} ms · 已确认排除 {{selectedMetric.excludedMs}} ms</small></article><article><span class="monitor-meta">已知区间可用率</span><strong>{{metricRatio(selectedMetric,'knownAvailability')}}</strong><small>{{selectedMetric.availableMs}} / {{selectedMetric.availableMs+selectedMetric.unavailableMs}} ms</small></article><article><span class="monitor-meta">已知区间覆盖率</span><strong>{{metricRatio(selectedMetric,'knownCoverage')}}</strong><small>{{selectedMetric.availableMs+selectedMetric.unavailableMs}} / {{selectedMetric.plannedMs}} ms</small></article><article><span class="monitor-meta">完整窗口可用率</span><strong>{{metricRatio(selectedMetric,'fullWindowAvailability')}}</strong><small v-if="selectedMetric.notApplicableMs">不适用 {{durationLabel(selectedMetric.notApplicableMs)}}</small><small v-else>{{selectedMetric.availableMs}} / {{selectedMetric.plannedMs}} ms</small></article><article><span class="monitor-meta">最长已知缺口</span><strong>{{durationLabel(selectedMetric.longestGapMs)}}</strong><small>已知中断 {{selectedMetric.gapCount}} 次</small></article></div><p v-for="reason in selectedMetric.limitations || []" :key="reason" class="monitor-hint">{{reasonText(reason)}}</p><p v-if="selectedMetric.intervalCount!=null" class="monitor-meta">该设备固定区间 {{selectedMetric.intervalCount}} 条 · 展示 {{selectedMetric.representedIntervalCount}} 条；固定发现 {{selectedMetric.originalFindingCount}} 条 · 展示 {{selectedMetric.representedFindingCount}} 条。时长与比例采用全部冻结依据。</p></div><ui-empty v-else description="当前筛选没有可计算的监测指标。"/>
   <MonitoringTimeline :intervals="visibleIntervals" :window="{start:run.start,end:run.end}" :devices="devices" :profiles="profiles" @select="row=>openFact(row,'interval')"/>
   <div class="monitor-card monitor-stack"><h3>已知数据缺口排行与未知区间</h3><p class="monitor-hint">按已知最长数据缺口排序。未知时长单独显示；策略、属性和整体指标不重复累加。</p><div class="monitor-table-scroll"><ui-table :data="rank" empty-text="暂无整体数据区间指标。"><ui-table-column label="设备" min-width="170"><template #default="{row}">{{deviceName(row.deviceId)}}</template></ui-table-column><ui-table-column label="已知不可用 / 最长缺口" min-width="210"><template #default="{row}">{{durationLabel(row.unavailableMs)}}<p class="monitor-meta">最长 {{durationLabel(row.longestGapMs)}} · {{row.gapCount}} 次</p></template></ui-table-column><ui-table-column label="未知 / 观察时长" min-width="190"><template #default="{row}">{{durationLabel(row.unknownMs)}}<p class="monitor-meta">计划观察 {{durationLabel(row.plannedMs)}}</p></template></ui-table-column><ui-table-column label="已知可用率 / 覆盖率" min-width="180"><template #default="{row}">{{metricRatio(row,'knownAvailability')}}<p class="monitor-meta">已知覆盖 {{metricRatio(row,'knownCoverage')}}</p></template></ui-table-column></ui-table></div></div>
   <div v-if="snapshot.statistics?.parseByDevice" class="monitor-card monitor-stack"><h3>归档与解析依据</h3><article v-for="[id,value] in Object.entries(snapshot.statistics.parseByDevice).filter(([id])=>matchesDevice(id))" :key="id"><strong>{{deviceName(id)}}</strong><p class="monitor-meta">观察原文 {{value.observedRaw}} 条 · 归档 {{value.archived}} 条 · 已尝试 {{value.attempted}} 条 · 未尝试 {{value.notAttempted}} 条 · 最后失败 {{value.lastFailed}} 条 · 最后成功 {{value.lastSucceeded}} 条 · 最后结果未知 {{value.unknownLast}} 条 · 成功标准消息 {{value.successfulStandardMessages}} 条</p><p v-for="reason in value.reasons || []" :key="reason" class="monitor-hint">{{reasonText(reason)}}</p></article><p class="monitor-hint">解析失败为最后一次结果，全部尝试历史缺失时不能给出累计失败率。连接保持、原文存在和关键属性有效分别核实。</p></div>
   <div class="monitor-card monitor-stack"><h3>获授权的接入依赖组</h3><p class="monitor-hint">比例仅使用本次获授权分析设备。接入关系不直接证明网络、电源或实体设施的共同故障。</p><div v-if="visibleGroups.length" class="monitor-group-grid"><article v-for="g in visibleGroups" :key="g.id" class="monitor-card"><strong>{{g.resourceName || (g.kind.toLowerCase().includes('parent')?deviceName(g.resourceId):dependencyKinds[g.kind] || g.kind)}}</strong><p class="monitor-meta">{{g.visibleDeviceCount}} / {{g.analysisDeviceCount}} 个本次可见设备 · {{g.analysisDeviceCount>0?((g.visibleDeviceCount/g.analysisDeviceCount)*100).toFixed(1)+'%':'不适用'}}</p><p class="monitor-hint">{{g.historyQuality==='CURRENT_ONLY'?'只有当前快照，历史依赖未覆盖':`历史有效 ${monitoringTime(g.start)} 至 ${monitoringTime(g.end)}`}}</p><ui-button :data-monitor-group="g.id" text size="small" @click="openGroup(g)">查看依赖依据与假设</ui-button></article></div><ui-empty v-else description="暂无可展示的授权接入组，请查看依赖来源和历史覆盖限制。"/></div>
   <div class="monitor-card monitor-stack"><h3>监测发现与人工核实</h3><div class="monitor-filter-row"><ui-select v-model="kindFilter" clearable placeholder="全部发现类型"><ui-option v-for="[value,label] in Object.entries(findingKinds)" :key="value" :value="value" :label="label"/></ui-select><ui-select v-model="reviewFilter" clearable placeholder="全部核实状态"><ui-option value="UNREVIEWED" label="尚未核实"/><ui-option v-for="[value,label] in Object.entries(reviewStates)" :key="value" :value="value" :label="label"/></ui-select></div><div class="monitor-table-scroll"><ui-table :data="pageFindings" empty-text="当前范围无监测发现，请同时核对未知区间和资料缺口。"><ui-table-column label="设备" min-width="180"><template #default="{row}">{{findingDevices(row).map(deviceName).join('、') || '本次分析范围'}}</template></ui-table-column><ui-table-column label="发现 / 固定依据" min-width="300"><template #default="{row}"><strong>{{findingKinds[row.kind] || row.kind}}</strong><p class="monitor-meta">{{row.explanation}}</p></template></ui-table-column><ui-table-column label="人工核实" min-width="160"><template #default="{row}">{{reviewStates[latestReview(row.id)?.result] || '尚未核实'}}</template></ui-table-column><ui-table-column label="操作" width="100"><template #default="{row}"><ui-button :data-monitor-finding="row.id" text size="small" @click="openFact(row)">依据与核实</ui-button></template></ui-table-column></ui-table></div><ui-pagination :current-page="findingPage" :page-size="20" :total="visibleFindings.length" @current-change="findingPage=$event"/></div>
   <div class="monitor-card monitor-stack"><div class="monitor-toolbar"><h3>AI 连续性解读</h3><ui-button v-if="can('POST /api/v1/monitoring-gaps/runs/:id/ai-jobs')" size="small" :loading="aiBusy" :disabled="aiJobs.some(row=>['QUEUED','RUNNING'].includes(row.status))" @click="runAI"><Sparkles/>{{activeAI?'重新解读':'开始解读'}}</ui-button></div><p class="monitor-hint">用户显式启动，解读绑定当前固定快照。人工核实、区间指标和报告导出独立保存。</p><ui-checkbox v-if="can('POST /api/v1/monitoring-gaps/runs/:id/ai-jobs')" v-model="useKnowledge">使用本工作流已绑定且获授权的知识</ui-checkbox><ui-alert v-if="aiError" :title="aiError" type="warning" :closable="false"/><ui-select v-if="aiJobs.length>1" v-model="aiId"><ui-option v-for="job in aiJobs" :key="job.id" :value="job.id" :label="`${monitoringTime(job.createdAt)} · ${stateLabel(job.status)}`"/></ui-select><template v-if="activeAI"><ui-tag :type="stateTone(activeAI.status)">{{stateLabel(activeAI.status)}}</ui-tag><p v-if="activeAI.error" class="monitor-hint">{{activeAI.error}}。固定事实仍可人工核实并导出。</p><p class="monitor-meta">快照版本 {{activeAI.snapshotVersion}} · {{activeAI.model || '模型由工作流配置'}} · 已提供事实 {{activeAI.factIds?.length || 0}} 条</p><p v-if="aiCoverage" class="monitor-meta">实际读取输出 {{aiCoverage.outputCount || 0}} / {{aiCoverage.totalOutputs || 0}} 条 · 证据 {{aiCoverage.evidenceCount || 0}} / {{aiCoverage.totalEvidence || 0}} 条{{aiCoverage.truncated?' · 仅覆盖部分事实':''}}</p><template v-if="activeAI.status==='SUCCEEDED'"><p>{{interpretation.summary}}</p><section v-for="[key,label] in aiSections" :key="key" class="monitor-stack"><h4>{{label}}</h4><article v-for="(statement,index) in interpretation[key] || []" :key="index"><p>{{statement.text}}</p><div class="monitor-tags"><ui-tag v-for="id in statement.deviceIds || []" :key="id" type="info">{{deviceName(id)}}</ui-tag><ui-button v-for="id in statement.factIds || []" :key="id" text size="small" @click="selectFact(id)">{{factLabel(id)}}</ui-button></div></article></section></template></template><p v-else class="monitor-meta">尚未生成连续性解读。</p></div>
  </template>
 </section>
 <ui-dialog v-model="groupDialog" title="固定接入依赖与假设影响" width="min(900px,94vw)" :close-on-click-modal="false" @close="groupDialog=false;groupGeneration++"><div class="monitor-dialog-body monitor-group-body"><template v-if="group"><div class="monitor-card"><strong>{{dependencyKinds[group.kind] || group.kind}}</strong><p class="monitor-meta">资源引用 {{group.resourceId}} · {{group.historyQuality==='CURRENT_ONLY'?'当前快照，历史未覆盖':'已知历史有效区间'}}</p><p class="monitor-meta">{{monitoringTime(group.start)}}{{group.historyQuality==='KNOWN'?' 至 '+monitoringTime(group.end):''}} · 本次可见 {{group.visibleDeviceCount}} / {{group.analysisDeviceCount}} 个设备</p><div class="monitor-tags"><ui-tag v-for="id in group.memberIds || []" :key="id" type="info">{{deviceName(id)}}</ui-tag></div></div><div class="monitor-card"><h3>依赖来源证据</h3><article v-for="ev in evidence.filter(row=>group.evidenceIds?.includes(row.id)||group.evidenceIds?.includes(row.sourceId))" :key="ev.id"><p class="monitor-meta">{{ev.sourceKind}} · {{monitoringTime(ev.occurredAt || ev.start)}} · {{ev.resourceVersion || ev.protocolVersion || '版本未记录'}}</p><p v-for="relation in ev.relationSources || []" :key="relation.id" class="monitor-meta">{{deviceName(relation.deviceId)}} · {{relation.kind}} · 来源事件 {{relation.sourceEventId || '未记录'}} · 版本 {{relation.resourceVersion || '未记录'}} · {{relation.quality}} · 记录于 {{monitoringTime(relation.recordedAt)}}<br>生效 {{monitoringTime(relation.effectiveFrom)}}{{relation.effectiveTo?' 至 '+monitoringTime(relation.effectiveTo):''}}</p><ui-button text size="small" @click="openFact(ev,'evidence')">查看固定依据</ui-button></article><p v-if="!evidence.some(row=>group.evidenceIds?.includes(row.id)||group.evidenceIds?.includes(row.sourceId))" class="monitor-hint">该组没有可读取的代表来源证据；关系汇总保留，资料不足须另行核实。</p></div><div class="monitor-card monitor-stack"><h3>假设此接入组不可用</h3><p class="monitor-hint">仅计算固定依赖成员中的可见设备，保留来源和版本依据。</p><ui-alert v-if="hypothesisError" :title="hypothesisError" type="error" :closable="false"/><ui-form v-if="can('POST /api/v1/monitoring-gaps/runs/:id/hypotheses')" label-position="top" :disabled="hypothesisSaving"><ui-form-item label="假设时点"><ui-date-time v-if="group.historyQuality==='KNOWN'" v-model="hypothesisAt"/><p v-else class="monitor-meta">采用固定当前快照时点 {{monitoringTime(group.start)}}，不进行历史推断。</p></ui-form-item><ui-button type="primary" size="small" :loading="hypothesisSaving" @click="createHypothesis">计算固定假设影响</ui-button></ui-form><article v-for="item in groupHistory" :key="item.id" class="monitor-card"><strong>假设影响本次可见设备 {{item.deviceIds.length}} 个</strong><p>{{item.deviceIds.map(deviceName).join('、')}}</p><p class="monitor-meta">假设时点 {{monitoringTime(item.at)}} · {{item.createdBy}} · 保存于 {{monitoringTime(item.createdAt)}}</p><p v-for="reason in item.limitations || []" :key="reason" class="monitor-hint">{{reasonText(reason)}}</p></article><p v-if="!groupHistory.length" class="monitor-meta">尚无已保存假设。</p></div></template></div><template #footer><ui-button :disabled="hypothesisSaving" @click="groupDialog=false">关闭</ui-button></template></ui-dialog>
 <ui-dialog v-model="factDialog" :title="detailTitle" width="min(980px,94vw)" :close-on-click-modal="false" @close="factDialog=false;detailGeneration++"><div class="monitor-dialog-body monitor-fact-body"><template v-if="fact"><div class="monitor-card"><strong>{{factType==='finding'?findingKinds[fact.kind] || fact.kind:factType==='interval'?intervalStates[fact.state]:'固定来源证据'}}</strong><p v-if="fact.explanation">{{fact.explanation}}</p><p class="monitor-meta">{{deviceName(fact.deviceId)}}{{fact.attributeId?' · '+fact.attributeId:''}} · {{fact.track?trackLabels[fact.track] || fact.track:''}}</p><p v-if="fact.start!=null" class="monitor-meta">{{monitoringTime(fact.start)}} 至 {{monitoringTime(fact.end)}} · {{durationLabel(fact.end-fact.start)}}</p><p v-for="reason in fact.reasons || []" :key="reason" class="monitor-hint">{{reasonText(reason)}}</p><div v-if="fact.values" class="monitor-table-scroll"><table class="monitor-native-table"><tbody><tr v-for="[key,value] in Object.entries(fact.values)" :key="key"><th>{{({thresholdMs:'时长门槛（ms）',longestGapMs:'最长缺口（ms）',gapCount:'中断次数',threshold:'次数门槛',unknownMs:'未知时长（ms）',plannedMs:'计划观察时长（ms）',overlapMs:'共同重叠（ms）',unionMs:'区间并集（ms）',jaccard:'Jaccard',policyVersion:'固定策略版本',deviceIds:'涉及本次可见设备'})[key] || key}}</th><td>{{key==='deviceIds'?value.map(deviceName).join('、'):typeof value==='object'?JSON.stringify(value):value}}</td></tr></tbody></table></div></div><div class="monitor-card monitor-stack"><h3>区间与代表来源依据</h3><article v-for="i in selectedIntervals" :key="i.id"><p>{{intervalStates[i.state]}} · {{trackLabels[i.track]}} · {{monitoringTime(i.start)}} 至 {{monitoringTime(i.end)}}</p><p v-for="reason in i.reasons || []" :key="reason" class="monitor-hint">{{reasonText(reason)}}</p></article><div class="monitor-table-scroll"><table class="monitor-native-table"><thead><tr><th>来源</th><th>设备事件时间</th><th>平台接收 / 首次可查询</th><th>原值 / 固定依据</th><th>原文</th></tr></thead><tbody><tr v-for="row in selectedEvidence" :key="row.id"><td>{{row.sourceKind}}<p class="monitor-meta">{{row.resourceVersion || '版本未记录'}}</p></td><td>{{monitoringTime(row.eventAt || row.occurredAt || row.start)}}</td><td>{{monitoringTime(row.receivedAt)}}<p class="monitor-meta">可查询 {{monitoringTime(row.availableAt)}}</p></td><td>{{row.value!=null?(typeof row.value==='object'?JSON.stringify(row.value):row.value):row.reason || row.basis || row.state || row.quality || '参照固定来源记录'}}</td><td><ui-button v-if="row.rawMessageId&&can('menu:raw')" text size="small" :disabled="['expired','missing','unavailable'].includes(row.availability)" @click="raw(row)">查看原文</ui-button><p class="monitor-meta">{{row.availability==='available_at_freeze'?'冻结时可用，当前未核实':row.availability==='expired'?'原文证据已过期':'当前原文可用性未确认'}}</p></td></tr><tr v-if="!selectedEvidence.length"><td colspan="5">未返回代表原文证据，固定区间指标仍保留，请结合来源限制核实。</td></tr></tbody></table></div></div><div v-if="factType==='finding'" class="monitor-card monitor-stack"><h3>人工核实记录</h3><ui-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><article v-for="item in history" :key="item.id"><ui-tag type="info">{{reviewStates[item.result] || item.result}}</ui-tag><p>{{item.explanation}}</p><p class="monitor-meta">{{item.reviewer}} · {{monitoringTime(item.reviewedAt)}}{{item.correctsId?' · 更正既有记录':''}}</p></article><p v-if="!history.length" class="monitor-meta">尚无核实记录。</p><ui-form v-if="can('POST /api/v1/monitoring-gaps/findings/:id/reviews')" label-position="top" :disabled="reviewSaving"><ui-form-item label="核实结果" required><ui-select v-model="review.result"><ui-option v-for="[value,label] in Object.entries(reviewStates)" :key="value" :value="value" :label="label"/></ui-select></ui-form-item><ui-form-item v-if="history.length" label="更正既有记录（选填）"><ui-select v-model="review.correctsId" clearable><ui-option v-for="item in history" :key="item.id" :value="item.id" :label="`${reviewStates[item.result]} · ${monitoringTime(item.reviewedAt)}`"/></ui-select></ui-form-item><ui-form-item label="实际核实依据" required><ui-input v-model="review.explanation" type="textarea" :rows="3" placeholder="填写接入、解析、运行或现场核实记录"/></ui-form-item><ui-button type="primary" size="small" :loading="reviewSaving" @click="saveReview">保存监测核实记录</ui-button></ui-form></div></template></div><template #footer><ui-button :disabled="reviewSaving" @click="factDialog=false">关闭</ui-button></template></ui-dialog>
</template>
<style scoped>.monitoring-results p,.monitor-fact-body p,.monitor-group-body p{overflow-wrap:anywhere;white-space:pre-wrap}.monitor-stat-grid small{display:block;color:var(--text-muted);font-size:11px;overflow-wrap:anywhere}.monitoring-results h4{font-size:13px;margin:0}.monitor-group-body .monitor-tags .n-tag{max-width:100%;white-space:normal;height:auto}</style>
